const isPostTypeOrTaxonomyName = `-- name: IsPostTypeOrTaxonomyName :one
SELECT (EXISTS (SELECT 1 FROM post_types WHERE name = $1::text)
     OR EXISTS (SELECT 1 FROM taxonomy_types WHERE name = $1::text))::boolean AS taken
`

// A category slug can't be a post type's or taxonomy's name: /{name}/... is that
// type's or taxonomy's URL, so /:category/:slug would never reach the post (#331).
func (q *Queries) IsPostTypeOrTaxonomyName(ctx context.Context, name string) (bool, error) {
	row := q.db.QueryRowContext(ctx, isPostTypeOrTaxonomyName, name)
	var taken bool
	err := row.Scan(&taken)
	return taken, err
}

