const lockPostForTerms = `-- name: LockPostForTerms :one

SELECT id, post_type FROM posts WHERE id = $1 FOR UPDATE
`

type LockPostForTermsRow struct {
	ID       int64  `json:"id"`
	PostType string `json:"post_type"`
}

// One category per post, the default category, merges (#331, 000047).
// Taken first by every write that replaces a post's category, so two writers of one
// post can't both pass the one-category check (000047's trigger is the backstop).
func (q *Queries) LockPostForTerms(ctx context.Context, id int64) (LockPostForTermsRow, error) {
	row := q.db.QueryRowContext(ctx, lockPostForTerms, id)
	var i LockPostForTermsRow
	err := row.Scan(&i.ID, &i.PostType)
	return i, err
}

const reassignTermPosts = `-- name: ReassignTermPosts :execrows
UPDATE post_taxonomy_relationships ptr
SET taxonomy_term_id = $1::bigint
WHERE ptr.taxonomy_term_id = $2::bigint
  AND NOT EXISTS (
    SELECT 1 FROM post_taxonomy_relationships other
    WHERE other.post_id = ptr.post_id AND other.taxonomy_term_id = $1::bigint
  )
`

type ReassignTermPostsParams struct {
	TargetID int64 `json:"target_id"`
	SourceID int64 `json:"source_id"`
}

// A merge (#331): the source's posts get the target, unless they have it already (the
// leftover links go with the source term).
func (q *Queries) ReassignTermPosts(ctx context.Context, arg ReassignTermPostsParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, reassignTermPosts, arg.TargetID, arg.SourceID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

